// A review with no reviewReply has not been answered. That is the whole state
// this workflow needs: nothing has to be logged to remember what was handled,
// and the same review cannot be answered twice even if a run is repeated.
const cfg = $('Settings').first().json;
const maxReviews = Number(cfg.max_reviews) || 20;

// The Business Profile API returns starRating as an enum STRING - "FIVE", not
// 5. Read as a number it is NaN, every comparison against it is false, and a
// five star review ends up looking like a one star complaint.
const STARS = { ONE: 1, TWO: 2, THREE: 3, FOUR: 4, FIVE: 5 };
function starsOf(r) {
  if (typeof r.starRating === 'number') return r.starRating;
  return STARS[String(r.starRating || '').toUpperCase()] || 0;
}

const out = [];
for (const item of $input.all()) {
  const r = item.json || {};
  // The node returns the review object directly on some paths and wrapped on
  // others, so both are accepted rather than guessed at.
  const rev = r.review || r;
  if (!rev || !rev.name) continue;
  if (rev.reviewReply && rev.reviewReply.comment) continue;

  const stars = starsOf(rev);
  out.push({
    review_name: rev.name,
    review_id: rev.reviewId || String(rev.name).split('/').pop(),
    reviewer: (rev.reviewer && rev.reviewer.displayName) || 'A customer',
    stars,
    comment: String(rev.comment || '').slice(0, 1500),
    created_at: rev.createTime || '',
  });
}

// Oldest first: a review that has been sitting unanswered for a week matters
// more than one from an hour ago.
out.sort((a, b) => String(a.created_at).localeCompare(String(b.created_at)));
const picked = out.slice(0, maxReviews);

// Never return zero items. A Code node that emits nothing ends the branch, so
// the quiet path below would never run and a day with no new reviews would look
// exactly like a broken workflow. The marker carries no review_name, which is
// what the IF routes on.
if (!picked.length) {
  return [{ json: { nothing_to_answer: true, reviews_seen: $input.all().length } }];
}
return picked.map((j) => ({ json: j }));

// One discovery per run, not one per review - hence executeOnce on this node.
// The rival field is a property of the business, not of any single review, and
// each discovery costs a Bright Data call and about two minutes.
const cfg = $('Settings').first().json;
const category = String(cfg.business_category || '').trim();
const city = String(cfg.city || '').trim();

if (!category || !city) {
  throw new Error('Set both business_category and city in Settings.');
}

// Bright Data's Maps discovery takes {keyword, country} and rejects a separate
// location field outright, so the city travels inside the keyword - the same
// way you would type it into Google Maps.
const payload = [{
  keyword: category + ' in ' + city,
  country: String(cfg.country || 'US').toUpperCase(),
}];

return [{ json: { payload, category, city } }];

// single-item input: the trigger endpoint answers once with one snapshot id.
const res = $input.first().json;

// Bright Data answers validation errors with HTTP 200 and an error body, and
// this node runs with neverError, so an unchecked response looks like a success
// and fails several nodes later blaming the wrong thing.
if (res.error || res.errors) {
  throw new Error('Bright Data rejected the search: ' + JSON.stringify(res.error || res.errors));
}
if (!res.snapshot_id) {
  throw new Error('No snapshot_id in the Bright Data response: ' + JSON.stringify(res).slice(0, 400));
}

return [{ json: { snapshot_id: res.snapshot_id } }];

const MAX_POLLS = 20; // 20 x 20s = about 7 minutes

// single-item input: the progress endpoint returns one status object.
const res = $input.first().json;
const snapshotId = $('Check Discovery Accepted').first().json.snapshot_id;
const attempt = $runIndex + 1;

if (res.error) {
  throw new Error('Progress check failed: ' + JSON.stringify(res.error));
}
if (res.status === 'failed') {
  throw new Error('Bright Data reported the snapshot failed: ' + JSON.stringify(res).slice(0, 400));
}
// Without this cap the false branch loops back to the Wait node forever and a
// stuck snapshot spins all night. Discovery measured 122 seconds for 2 records.
if (res.status !== 'ready' && attempt >= MAX_POLLS) {
  throw new Error(
    'Snapshot ' + snapshotId + ' still ' + res.status + ' after ' + attempt +
    ' polls. Raise MAX_POLLS or lower rivals_to_compare.'
  );
}

return [{ json: { status: res.status, snapshot_id: snapshotId, attempt, records: res.records || 0 } }];

// Turns the rival rows into one item per unanswered review, each carrying the
// same local picture. The reviews are read by name because this node sits
// downstream of the Bright Data branch, which knows nothing about them.
const cfg = $('Settings').first().json;
const reviews = $('Find Unanswered Reviews').all().map((x) => x.json).filter((r) => r.review_name);
const ourName = String(cfg.business_name || '').trim().toLowerCase();

const rivals = [];
for (const item of $input.all()) {
  const r = item.json || {};
  if (r.error || !r.name) continue;
  // Your own listing comes back inside your own category search. Comparing you
  // against yourself would drag the average towards your own number and make
  // the gap look smaller than it is.
  if (ourName && String(r.name).trim().toLowerCase() === ourName) continue;
  if (r.permanently_closed) continue;
  const rating = Number(r.rating);
  if (!rating) continue;
  rivals.push({
    name: r.name,
    rating,
    reviews_count: Number(r.reviews_count) || 0,
    category: r.category || '',
    // Measured at 8 entries per business, each with a numeric rating and the
    // review text. The five star ones are what the rival is praised for.
    praise: (r.top_reviews || [])
      .filter((t) => Number(t.rating) >= 4 && t.content)
      .slice(0, 4)
      .map((t) => String(t.content).replace(/\s+/g, ' ').slice(0, 220)),
  });
}

rivals.sort((a, b) => b.rating - a.rating || b.reviews_count - a.reviews_count);

const avg = rivals.length
  ? Math.round((rivals.reduce((s, r) => s + r.rating, 0) / rivals.length) * 100) / 100
  : 0;
const best = rivals[0] || null;

// Praise lines from the highest rated rivals, deduplicated, as the material the
// model is told to write towards rather than invent from nothing.
const praise = [];
for (const r of rivals) {
  for (const p of r.praise) {
    if (praise.length >= 6) break;
    if (!praise.some((x) => x.text === p)) praise.push({ rival: r.name, text: p });
  }
}

const context = {
  business_name_display: String(cfg.business_name || 'this business'),
  rivals_compared: rivals.length,
  rival_avg_rating: avg,
  best_rival: best ? best.name : '',
  best_rival_rating: best ? best.rating : 0,
  rival_praise: praise,
  rival_table: rivals
    .slice(0, 6)
    .map((r) => r.name + ' ' + r.rating + ' (' + r.reviews_count + ' reviews)'),
};

if (!reviews.length) {
  return [{ json: { nothing_to_answer: true } }];
}
return reviews.map((rev) => ({ json: { ...rev, ...context } }));

