// The Information Extractor does not merge its answer into the item, it
// REPLACES it - every row arrives as {output: {...}} and nothing else. The
// review name is gone by this point, so the join back is positional, on the
// same order the extractor received. Matching on a field that no longer exists
// finds nothing and leaves every reply blank on a fully green run.
const cfg = $('Settings').first().json;
const REPLY_LIMIT = 700; // the API allows 4096; a wall of text reads as a bot
const autoReply = cfg.auto_reply === true || cfg.auto_reply === 'true';
const source = $('Build Local Benchmark').all().map((x) => x.json);
const items = $input.all();
const out = [];

// The model ignores the schema's enum often enough to plan for, so the flag is
// folded back to a real boolean instead of whatever word came back.
function wantsHuman(v) {
  const s = String(v == null ? '' : v).toLowerCase();
  return s === 'yes' || s === 'true' || s === 'y';
}

for (let i = 0; i < items.length; i++) {
  const src = source[i];
  if (!src || !src.review_name) continue;
  const j = items[i].json || {};
  const a = (j.output && typeof j.output === 'object') ? j.output : j;

  const reply = String(a.reply || '').trim();
  let hold = '';
  if (!reply) {
    hold = 'the model returned no reply text';
  } else if (wantsHuman(a.escalate)) {
    hold = 'flagged for a person to answer';
  } else if (reply.length > REPLY_LIMIT) {
    // Truncating a public apology mid-sentence is worse than not posting it.
    hold = 'draft is ' + reply.length + ' characters, over the ' + REPLY_LIMIT + ' cap';
  } else if (src.stars <= 2) {
    // A one or two star review is a complaint in public. Even with auto_reply
    // on, those are worth a person's eyes.
    hold = 'low rating, worth answering personally';
  }

  out.push({
    ...src,
    reply_text: reply,
    theme: String(a.theme || '').slice(0, 60),
    hold_reason: hold,
    // Both conditions have to hold. auto_reply alone is not enough to publish.
    should_publish: Boolean(autoReply && !hold && reply),
  });
}

if (!out.length) {
  return [{ json: { nothing_to_answer: true } }];
}
return out;

// Reads the drafts by name rather than from this node's input, because the
// publish branch only carries the ones that were actually posted.
const cfg = $('Settings').first().json;
const rows = $('Assemble Replies').all().map((x) => x.json).filter((r) => r.review_name);

if (!rows.length) {
  return [{ json: { message: 'Review check ran and found nothing to answer.', rows: [] } }];
}

const posted = rows.filter((r) => r.should_publish);
const held = rows.filter((r) => !r.should_publish);
const first = rows[0];

const lines = [
  '*Google reviews* - ' + rows.length + ' unanswered, ' +
    (cfg.auto_reply === true || cfg.auto_reply === 'true'
      ? posted.length + ' posted, ' + held.length + ' held for you'
      : 'all drafted, nothing posted (auto_reply is off)'),
  'Local field: ' + (first.rivals_compared || 0) + ' rivals average ' + (first.rival_avg_rating || 0) +
    (first.best_rival ? ', best is ' + first.best_rival + ' at ' + first.best_rival_rating : ''),
  '',
];

for (const r of rows) {
  lines.push('*' + r.stars + '\u2605 ' + r.reviewer + '*' + (r.theme ? '  _' + r.theme + '_' : ''));
  lines.push('   > ' + String(r.comment || '').slice(0, 180));
  lines.push('   ' + (r.reply_text || '(no draft)'));
  lines.push('   ' + (r.should_publish ? '_posted to Google_' : '_held: ' + (r.hold_reason || 'auto_reply off') + '_'));
  lines.push('');
}

return [{ json: { message: lines.join('\n'), rows } }];

// Optional. Splice between 'Assemble Replies' and 'Publish Or Hold?' when a
// location serves customers in more than one language. Google shows the reply
// under the review, so it reads best in the language the reviewer used.
const target = 'es';
return items.map((item) => {
  const j = item.json || {};
  return { json: { ...j, reply_language: target, needs_translation: String(j.review_language || 'en') !== target } };
});
